const express = require("express");
const { createClient } = require("@clickhouse/client");

const app = express();
const PORT = process.env.PORT || 3000;

const clickhouse = createClient({
  url: process.env.CLICKHOUSE_URL || "http://localhost:8123",
  database: "analytics",
});

app.get("/api/events", async (req, res) => {
  try {
    const limit = Math.max(1, Math.min(1000, parseInt(req.query.limit, 10) || 20));
    const offset = Math.max(0, parseInt(req.query.offset, 10) || 0);

    const [countResult, dataResult] = await Promise.all([
      clickhouse.query({
        query: "SELECT count() AS total FROM events",
        format: "JSONEachRow",
      }),
      clickhouse.query({
        query: `SELECT event_id, event_ts, event_type, user_id FROM events ORDER BY event_ts, event_id LIMIT {limit:UInt32} OFFSET {offset:UInt32}`,
        query_params: { limit, offset },
        format: "JSONEachRow",
      }),
    ]);

    const [{ total }] = await countResult.json();
    const data = await dataResult.json();

    res.json({
      data,
      total: Number(total),
      limit,
      offset,
      hasMore: offset + data.length < Number(total),
    });
  } catch (err) {
    console.error("Query error:", err);
    res.status(500).json({ error: "Internal server error" });
  }
});

app.listen(PORT, () => {
  console.log(`Server listening on port ${PORT}`);
});

